package com.company.tpm.telegram;import com.company.tpm.audit.AuditService;import com.company.tpm.employee.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TelegramAccountService{private final TelegramLinkRepository links;private final EmployeeRepository employees;private final AuditService audit;public TelegramAccountService(TelegramLinkRepository l,EmployeeRepository e,AuditService a){links=l;employees=e;audit=a;}@Transactional public TelegramLink link(String staffId,long userId,long chatId){var e=employees.findByStaffId(staffId).orElseThrow(()->new IllegalArgumentException("Employee not found"));if(e.getStatus()!=Employee.Status.ACTIVE)throw new IllegalArgumentException("Employee is not active");if(links.findByTelegramUserIdAndActiveTrue(userId).isPresent()||links.findByEmployeeIdAndActiveTrue(e.getId()).isPresent())throw new IllegalArgumentException("An active Telegram link already exists");var link=links.save(new TelegramLink(e,userId,chatId));audit.record(staffId,"TELEGRAM_LINKED","Employee",e.getId(),Map.of("telegramUserId",userId));return link;}@Transactional public void disconnect(long userId){var l=links.findByTelegramUserIdAndActiveTrue(userId).orElseThrow(()->new IllegalArgumentException("Link not found"));l.disconnect();audit.record(l.getEmployee().getStaffId(),"TELEGRAM_UNLINKED","Employee",l.getEmployee().getId(),Map.of());}}
